import { useMemo, useState, useCallback } from "react";
import type {
  Account,
  VirtualBankAccount,
} from "@venlyfinance/sdk";
import {
  useAccount,
  useVirtualBankAccounts,
  useCreateVirtualBankAccount,
} from "@venlyfinance/react";
import { FieldList, type FieldRow } from "../components/field-list.js";
import { StatusPill } from "../components/status-pill.js";

import type { CSSProperties, ReactElement } from "react";

// Constants
const REFERENCE_WARNING =
  "Enter the payment reference exactly as shown. If it is missing or changed, the payment cannot be matched automatically and may require manual reconciliation. If your bank cannot accept the reference exactly as shown, stop and contact the recipient before sending.";

const FRAUD_CHECK_ADVISORY =
  "If these details differ from instructions you used before, confirm the change with the recipient through a trusted channel before sending.";

const CURRENCY_DISPLAY: Record<string, string> = {
  EUR_SEPA: "SEPA",
};

// Serializer
export interface ReceiveDetails {
  name: string;
  iban: string;
  bic: string;
  bankName: string;
  beneficiaryName: string;
  referenceCode: string;
  currency: string;
  bankAccountType: string;
  targetCryptocurrency?: string;
}

export function serializeReceiveDetails(details: ReceiveDetails): string {
  const lines: string[] = [];
  const now = new Date();
  lines.push("Bank transfer instructions");
  lines.push(
    `Generated: ${now.toLocaleDateString("en-GB", {
      day: "2-digit",
      month: "2-digit",
      year: "numeric",
    })} ${now.toLocaleTimeString("en-GB", {
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    })} ${now.getTimezoneName()}`
  );
  lines.push("");
  lines.push("Important");
  lines.push(REFERENCE_WARNING);
  lines.push("");
  lines.push("Payment reference (required)");
  lines.push(details.referenceCode);
  lines.push(details.beneficiaryName);
  lines.push(details.iban);
  lines.push(details.bic);
  lines.push(details.bankName);
  lines.push(`Currency to send: ${details.currency}`);
  lines.push(
    `Transfer type: ${
      CURRENCY_DISPLAY[details.bankAccountType] ?? "SEPA"
    } bank transfer`
  );
  lines.push("");
  lines.push("Currency conversion");
  lines.push(
    details.targetCryptocurrency
      ? `Send ${details.currency}, not ${details.targetCryptocurrency}. The recipient account converts incoming ${details.currency} to ${details.targetCryptocurrency}.`
      : `Send ${details.currency}. (No conversion takes place.)`
  );
  lines.push("");
  lines.push("Fraud check");
  lines.push(FRAUD_CHECK_ADVISORY);
  return lines.join("\n");
}

// Clipboard helper
export async function copyText(value: string): Promise<boolean> {
  if (typeof navigator === "undefined" || !navigator.clipboard) return false;
  try {
    await navigator.clipboard.writeText(value);
    return true;
  } catch {
    return false;
  }
}

// PDF adapter (dependency-light)
function sanitizeFileName(base: string): string {
  return base.replace(/[\W]/g, "_").slice(0, 40).toLowerCase();
}

export function downloadPDF(
  details: ReceiveDetails,
  name: string,
  generateClock: () => string = () => new Date().toLocaleString()
): void {
  const now = generateClock();
  const dateStr =
    name && name.trim().length > 0
      ? `${sanitizeFileName(name)}-${now.split(",")[0].replace(/\//g, "-").replace(/ /g, "-")}`
      : now.split(",")[0].replace(/\//g, "-").replace(/ /g, "-");

  const html = `<!doctype html>
<html><head><title>Bank transfer instructions</title>
<style>body{font-family:sans-serif;padding:48px;max-width:600px}
h1{font-size:18px;margin-bottom:8px}h2{font-size:14px;margin-top:24px;margin-bottom:4px;color:#555}
p{margin:4px 0;font-size:13px;line-height:1.4}table{width:100%;border-collapse:collapse;margin:8px 0}
td,th{text-align:left;padding:4px 0;font-size:13px;border-bottom:1px solid #eee}
th{width:140px;color:#555}</style></head><body>
<h1>Bank transfer instructions</h1>
<p>Generated: ${now}</p>
<h2>Important</h2>
<p>${REFERENCE_WARNING}</p>
<table>
<tr><th>Payment reference</th><td><strong>${details.referenceCode}</strong><br/><span style="color:#b8860b;font-size:11px">(required)</span></td></tr>
<tr><td>Beneficiary name</td><td>${details.beneficiaryName}</td></tr>
<tr><td>IBAN</td><td><strong>${details.iban}</strong></td></tr>
<tr><td>BIC / SWIFT code</td><td><strong>${details.bic}</strong></td></tr>
<tr><td>Bank name</td><td>${details.bankName}</td></tr>
<tr><td>Currency to send</td><td>${details.currency}</td></tr>
<tr><td>Transfer type</td><td>${CURRENCY_DISPLAY[details.bankAccountType] ?? "SEPA"} bank transfer</td></tr>
</table>
<h2>Currency conversion</h2>
<p>${details.targetCryptocurrency ? `Send ${details.currency}, not ${details.targetCryptocurrency}. The recipient account converts incoming ${details.currency} to ${details.targetCryptocurrency}.` : `Send ${details.currency}. (No conversion takes place.)`}</p>
<h2>Fraud check</h2>
<p>${FRAUD_CHECK_ADVISORY}</p>
</body></html>`;

  const win = window.open("", "_blank");
  if (!win) return;
  win.document.write(html);
  win.document.close();
  win.focus();
  setTimeout(() => {
    win.print();
    setTimeout(() => win.close(), 2000);
  }, 300);
}

// Completeness helper
const REQUIRED_FIELDS: (keyof VirtualBankAccount)[] = [
  "referenceCode",
  "beneficiaryName",
  "iban",
  "bic",
  "bankName",
  "currency",
  "bankAccountType",
  "targetCryptocurrency",
];

export function isComplete(vba: VirtualBankAccount): boolean {
  return REQUIRED_FIELDS.every((k) => {
    const v = vba[k];
    return v !== undefined && v !== null && v !== "";
  });
}

// Connected entry point
export function ConnectedReceiveBlock({
  accountId,
}: {
  accountId: string;
}): ReactElement | null {
  const {
    data: accountData,
    isLoading: accountLoading,
    isError: accountError,
  } = useAccount(accountId);

  const account = useMemo(() => {
    if (!accountData || typeof accountData !== "object") return null;
    return "result" in accountData
      ? (accountData.result as Account | undefined)
      : (accountData as unknown as Account);
  }, [accountData]);

  const vbaQuery = useVirtualBankAccounts(accountId);
  const vbaRaw = useMemo(() => {
    if (!vbaQuery.data) return { items: [], pagination: null };
    const d = vbaQuery.data as {
      items: (VirtualBankAccount | null)[];
      pagination?: {
        pageNumber?: number;
        numberOfElements?: number;
        numberOfPages?: number;
        hasNextPage?: boolean;
        hasPreviousPage?: boolean;
      };
    };
    return {
      items: d.items.filter((i): i is VirtualBankAccount => i != null),
      pagination: d.pagination ?? null,
    };
  }, [vbaQuery.data]);

  const validItems = useMemo(
    () =>
      vbaRaw.items.filter((v) =>
        v.id && v.status === "ACTIVE"
      ),
    [vbaRaw.items]
  );

  const autoSelectSingle =
    vbaRaw.pagination &&
    vbaRaw.pagination.numberOfPages === 1 &&
    vbaRaw.pagination.numberOfElements === 1 &&
    validItems.length === 1;

  const createMutation = useCreateVirtualBankAccount(accountId);

  // Loading
  if (accountLoading || vbaQuery.isLoading) {
    return (
      <section style={{ fontFamily: "var(--font-family)" }}>
        <p style={{ color: "var(--text-tertiary)" }}>
          Loading bank details...
        </p>
      </section>
    );
  }

  // Sparse account
  if (!account?.kycStatus) {
    return (
      <section style={{ fontFamily: "var(--font-family)" }}>
        <p style={{ color: "var(--text-secondary)", fontStyle: "italic" }}>
          Account status unavailable
        </p>
        <p style={{ color: "var(--text-tertiary)" }}>
          Bank details can't be created or shared until the account status is
          available.
        </p>
      </section>
    );
  }

  // Verification pending / rejected
  if (
    account.kycStatus === "VERIFICATION_PENDING" ||
    account.kycStatus === "REJECTED"
  ) {
    return null; // handled via separate page
  }

  // Single valid VBA
  if (autoSelectSingle) {
    return (
      <DetailView vba={validItems[0]} account={account!} />
    );
  }

  // Multiple
  return (
    <MultipleView vbaList={vbaRaw.items} pagination={vbaRaw.pagination} />
  );
}

// Detail view
interface DetailViewProps {
  vba: VirtualBankAccount;
  account: Account;
}

function DetailView({ vba, account }: DetailViewProps): ReactElement {
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [copyError, setCopyError] = useState<string | null>(null);
  const complete = isComplete(vba);

  const handleFieldCopy = useCallback(
    async (label: string, value: string): Promise<void> => {
      if (!complete) {
        setCopyError(
          `${label} wasn't copied. Select and copy the value manually, or try again.`
        );
        return;
      }
      const ok = await copyText(value);
      if (ok) {
        setCopiedField(`${label} copied.`);
        setTimeout(() => setCopiedField(null), 1500);
      }
    },
    [complete]
  );

  const handleCopyAll = useCallback(async (): Promise<void> => {
    if (!complete) {
      setCopyError(
        "Bank transfer details weren't copied. Try again or download the PDF."
      );
      return;
    }
    const details: ReceiveDetails = {
      name: account.name ?? "Unnamed bank details",
      iban: vba.iban ?? "",
      bic: vba.bic ?? "",
      bankName: vba.bankName ?? "",
      beneficiaryName: vba.beneficiaryName ?? "",
      referenceCode: vba.referenceCode ?? "",
      currency: vba.currency ?? "",
      bankAccountType: vba.bankAccountType ?? "",
      targetCryptocurrency: vba.targetCryptocurrency ?? undefined,
    };
    const ok = await copyText(serializeReceiveDetails(details));
    if (ok) setCopiedField("Bank transfer details copied.");
    else
      setCopyError(
        "Bank transfer details weren't copied. Try again or download the PDF."
      );
    setTimeout(() => setCopiedField(null), 2000);
  }, [complete, account, vba]);

  const handleDownloadPDF = useCallback((): void => {
    if (!complete) {
      setCopyError(
        "The PDF wasn't created. Try again or copy the details as text."
      );
      return;
    }
    const details: ReceiveDetails = {
      name: account.name ?? "Unnamed bank details",
      iban: vba.iban ?? "",
      bic: vba.bic ?? "",
      bankName: vba.bankName ?? "",
      beneficiaryName: vba.beneficiaryName ?? "",
      referenceCode: vba.referenceCode ?? "",
      currency: vba.currency ?? "",
      bankAccountType: vba.bankAccountType ?? "",
      targetCryptocurrency: vba.targetCryptocurrency ?? undefined,
    };
    downloadPDF(details, account.name ?? "Unnamed bank details");
  }, [complete, account, vba]);

  // CLOSED
  if (vba.status === "CLOSED") {
    return (
      <section style={{ fontFamily: "var(--font-family)" }}>
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "baseline",
            marginBottom: "var(--space-sm)",
          }}
        >
          <span
            style={{
              fontSize: "var(--font-size-value)",
              fontWeight: 600,
              color: "var(--text-primary)",
            }}
          >
            {account.name ?? "Unnamed bank details"}
          </span>
        </div>
        <StatusPill
          label="Bank details status – Closed"
          intent="negative"
        />
        <p style={{ color: "var(--text-secondary)" }}>
          These bank details are closed. Do not share or use them for a
          new transfer.
        </p>
      </section>
    );
  }

  // Complete
  if (complete) {
    return (
      <section style={{ fontFamily: "var(--font-family)" }}>
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "baseline",
            marginBottom: "var(--space-sm)",
          }}
        >
          <span
            style={{
              fontSize: "var(--font-size-value)",
              fontWeight: 600,
              color: "var(--text-primary)",
            }}
          >
            {account.name ?? "Unnamed bank details"}
          </span>
          <div style={{ display: "flex", gap: "var(--space-sm)" }}>
            <button
              type="button"
              onClick={handleCopyAll}
              style={{
                border:
                  "var(--border-w-hairline) solid var(--border-strong)",
                background: "var(--surface-raised)",
                borderRadius: "var(--radius-control)",
                padding: "var(--space-sm) var(--space-lg)",
                fontSize: "var(--font-size-label)",
                fontWeight: 500,
                color: "var(--text-primary)",
                cursor: "pointer",
              }}
            >
              {copiedField?.includes("Bank transfer")
                ? "Copied!"
                : "Copy details"}
            </button>
            <button
              type="button"
              onClick={handleDownloadPDF}
              style={{
                border:
                  "var(--border-w-hairline) solid var(--border-strong)",
                background: "var(--surface-raised)",
                borderRadius: "var(--radius-control)",
                padding: "var(--space-sm) var(--space-lg)",
                fontSize: "var(--font-size-label)",
                fontWeight: 500,
                color: "var(--text-primary)",
                cursor: "pointer",
              }}
            >
              Download PDF
            </button>
          </div>
        </div>
        <StatusPill
          label="Bank details status – Active"
          intent="positive"
        />
        <p
          style={{
            fontSize: "var(--font-size-label)",
            color: "var(--text-secondary)",
            marginTop: "var(--space-md)",
          }}
        >
          EUR · SEPA
        </p>
        <div role="alert" style={{ marginTop: "var(--space-md)" }}>
          <p
            style={{
              background: "var(--state-pending-bg)",
              color: "var(--state-pending-fg)",
              borderRadius: "var(--radius-control)",
              padding: "var(--space-sm) var(--space-md)",
              fontSize: "var(--font-size-label)",
            }}
          >
            {REFERENCE_WARNING}
          </p>
        </div>
        <FieldList
          fields={[
            {
              label: "Payment reference",
              value: vba.referenceCode ?? "",
              mono: true,
              required: true,
            },
            {
              label: "Beneficiary name",
              value: vba.beneficiaryName ?? "",
            },
            { label: "IBAN", value: vba.iban ?? "", mono: true },
            {
              label: "BIC / SWIFT code",
              value: vba.bic ?? "",
              mono: true,
            },
            {
              label: "Bank name",
              value: vba.bankName ?? "",
              copyable: false,
            },
            {
              label: "Currency to send",
              value: vba.currency ?? "",
            },
            {
              label: "Transfer type",
              value: `${CURRENCY_DISPLAY[vba.bankAccountType] ?? "SEPA"} bank transfer`,
              copyable: false,
            },
          ]}
          onCopy={handleFieldCopy}
        />
        {vba.targetCryptocurrency ? (
          <p
            style={{
              fontSize: "var(--font-size-micro)",
              color: "var(--text-secondary)",
              fontStyle: "italic",
              marginTop: "var(--space-md)",
            }}
          >
            Send {vba.currency}, not {vba.targetCryptocurrency}. The
            recipient account converts incoming {vba.currency} to
            {" "}
            {vba.targetCryptocurrency}.
          </p>
        ) : null}
        {copiedField && (
          <div
            style={{
              position: "fixed",
              bottom: "var(--space-lg)",
              left: "50%",
              transform: "translateX(-50%)",
              background: "var(--surface-raised)",
              color: "var(--text-primary)",
              borderRadius: "var(--radius-control)",
              padding: "var(--space-sm) var(--space-md)",
              fontSize: "var(--font-size-label)",
              boxShadow: "0 2px 8px rgba(0,0,0,0.15)",
              zIndex: 100,
            }}
            role="status"
            aria-live="polite"
          >
            {copiedField}
          </div>
        )}
        {copyError && (
          <div
            style={{
              marginTop: "var(--space-sm)",
              fontSize: "var(--font-size-label)",
              color: "var(--text-secondary)",
            }}
          >
            {copyError}
          </div>
        )}
      </section>
    );
  }

  // Incomplete
  return (
    <BlockedView vba={vba} account={account} />
  );
}

// Blocked view
function BlockedView({
  vba,
  account,
}: Pick<DetailViewProps, "vba" | "account">): ReactElement {
  const [copyError, setCopyError] = useState<string | null>(null);

  return (
    <section style={{ fontFamily: "var(--font-family)" }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "baseline",
          marginBottom: "var(--space-sm)",
        }}
      >
        <span
          style={{
            fontSize: "var(--font-size-value)",
            fontWeight: 600,
            color: "var(--text-primary)",
          }}
        >
          Bank transfer instructions
        </span>
      </div>
      <StatusPill
        label="Bank details status – Active"
        intent="positive"
      />
      <div
        role="alert"
        style={{
          background: "var(--state-pending-bg)",
          color: "var(--state-pending-fg)",
          borderRadius: "var(--radius-control)",
          padding: "var(--space-sm) var(--space-md)",
          fontSize: "var(--font-size-label)",
          marginTop: "var(--space-sm)",
        }}
      >
        <strong>Bank transfer instructions are incomplete.</strong>
        <p style={{ margin: "8px 0 0" }}>
          One or more required fields are unavailable. Copying and download
          are disabled so incomplete instructions cannot be sent.
        </p>
      </div>
      <div style={{ display: "flex", gap: "var(--space-sm)" }}>
        <button
          type="button"
          disabled
          style={{
            border:
              "var(--border-w-hairline) solid var(--border-strong)",
            background: "var(--surface-raised)",
            borderRadius: "var(--radius-control)",
            padding: "var(--space-sm) var(--space-lg)",
            fontSize: "var(--font-size-label)",
            fontWeight: 500,
            color: "var(--text-tertiary)",
            cursor: "not-allowed",
          }}
        >
          Copy details
        </button>
        <button
          type="button"
          disabled
          style={{
            border:
              "var(--border-w-hairline) solid var(--border-strong)",
            background: "var(--surface-raised)",
            borderRadius: "var(--radius-control)",
            padding: "var(--space-sm) var(--space-lg)",
            fontSize: "var(--font-size-label)",
            fontWeight: 500,
            color: "var(--text-tertiary)",
            cursor: "not-allowed",
          }}
        >
          Download PDF
        </button>
      </div>
      <FieldList
        fields={[
          {
            label: "Payment reference",
            value: vba.referenceCode ?? "Unavailable",
            mono: true,
            required: true,
          },
          {
            label: "Beneficiary name",
            value: vba.beneficiaryName ?? "Unavailable",
          },
          { label: "IBAN", value: vba.iban ?? "Unavailable", mono: true },
          {
            label: "BIC / SWIFT code",
            value: vba.bic ?? "Unavailable",
            mono: true,
          },
          {
            label: "Bank name",
            value: vba.bankName ?? "Unavailable",
            copyable: false,
          },
          {
            label: "Currency to send",
            value: vba.currency ?? "Unavailable",
          },
          {
            label: "Transfer type",
            value: `${CURRENCY_DISPLAY[vba.bankAccountType ?? "EUR_SEPA"] ?? "SEPA"} bank transfer`,
            copyable: false,
          },
        ]}
        onCopy={async (label, value) => {
          if (value === "Unavailable") {
            setCopyError(
              `${label} wasn't copied. Select and copy the value manually, or try again.`
            );
          }
        }}
      />
      <div style={{ marginTop: "var(--space-sm)" }}>
        <button
          type="button"
          onClick={() => window.location.reload()}
          style={{
            border: "none",
            background: "none",
            color: "var(--text-secondary)",
            cursor: "pointer",
            fontSize: "var(--font-size-label)",
            textDecoration: "underline",
          }}
        >
          Reload bank details
        </button>
      </div>
    </section>
  );
}

// Multiple view
function MultipleView({
  vbaList,
  pagination,
}: {
  vbaList: (VirtualBankAccount | null)[];
  pagination: {
    pageNumber?: number;
    numberOfElements?: number;
    numberOfPages?: number;
    hasNextPage?: boolean;
    hasPreviousPage?: boolean;
  } | null;
}): ReactElement {
  return (
    <section style={{ fontFamily: "var(--font-family)" }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "baseline",
          marginBottom: "var(--space-sm)",
        }}
      >
        <span
          style={{
            fontSize: "var(--font-size-value)",
            fontWeight: 600,
            color: "var(--text-primary)",
          }}
        >
          Choose bank details
        </span>
      </div>
      <p style={{ color: "var(--text-secondary)" }}>
        Select the bank details you want to share.
      </p>
      <div style={{ marginTop: "var(--space-sm)" }}>
        <select
          style={{
            width: "100%",
            padding: "var(--space-sm)",
            fontSize: "var(--font-size-body)",
            fontFamily: "var(--font-family)",
            border:
              "var(--border-w-hairline) solid var(--border-strong)",
            borderRadius: "var(--radius-control)",
          }}
        >
          <option value="">Select bank details</option>
          {vbaList
            .filter((v): v is VirtualBankAccount => v != null)
            .map((v) => (
              <option key={v.id} value={v.id}>
                {v.name ?? "Unnamed bank details"} -{" "}
                {v.status === "ACTIVE" ? "Active" : "Closed"}
              </option>
            ))}
        </select>
      </div>
      {pagination && (
        <div style={{ display: "flex", gap: "var(--space-xs)", marginTop: "var(--space-xs)" }}>
          <button disabled={!pagination.hasPreviousPage}>
            Previous
          </button>
          <span>
            Page {pagination.pageNumber ?? 1} of{" "}
            {pagination.numberOfPages ?? 1}
          </span>
          <button disabled={!pagination.hasNextPage}>Next</button>
        </div>
      )}
      <p style={{ color: "var(--text-tertiary)", fontStyle: "italic", marginTop: "var(--space-sm)" }}>
        Loading...
      </p>
    </section>
  );
}

// Presentational block
export interface ReceiveBlockProps {
  virtualBankAccount: VirtualBankAccount;
  onCopied?: (field: string, value: string) => void;
  style?: CSSProperties;
  className?: string;
}

export function ReceiveBlock({
  virtualBankAccount: viba,
  onCopied,
  style,
  className,
}: ReceiveBlockProps): ReactElement {
  const fields: FieldRow[] = [
    {
      label: "Beneficiary",
      value: viba.beneficiaryName,
    },
    { label: "IBAN", value: viba.iban, mono: true },
    { label: "BIC", value: viba.bic, mono: true },
    { label: "Bank", value: viba.bankName, copyable: false },
    {
      label: "Payment reference",
      value: viba.referenceCode,
      mono: true,
      required: true,
    },
  ];

  const copyAll = async () => {
    const text = fields
      .filter((f) => f.value)
      .map((f) => `${f.label}: ${f.value}`)
      .join("\n");
    if (await copyText(text)) onCopied?.("all", text);
  };

  return (
    <section
      className={className}
      style={{
        fontFamily: "var(--font-family)",
        maxWidth: "var(--card-max-width)",
        ...style,
      }}
    >
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "baseline",
          marginBottom: "var(--space-sm)",
        }}
      >
        <span
          style={{
            fontSize: "var(--font-size-value)",
            fontWeight: 600,
            color: "var(--text-primary)",
          }}
        >
          Receive {viba.currency ?? ""}
        </span>
        <button
          type="button"
          onClick={copyAll}
          style={{
            border:
              "var(--border-w-hairline) solid var(--border-strong)",
            background: "var(--surface-raised)",
            borderRadius: "var(--radius-control)",
            padding: "var(--space-sm) var(--space-md)",
            fontSize: "var(--font-size-label)",
            fontWeight: 500,
            color: "var(--text-primary)",
            cursor: "pointer",
          }}
        >
          Copy all
        </button>
      </div>
      <div
        role="alert"
        style={{
          background: "var(--state-pending-bg)",
          color: "var(--state-pending-fg)",
          borderRadius: "var(--radius-control)",
          padding: "var(--space-sm) var(--space-md)",
          fontSize: "var(--font-size-label)",
          marginBottom: "var(--space-sm)",
        }}
      >
        The payment reference must be included word for word - transfers without it cannot be
        matched to this account and will be held until claimed.
      </div>
      <FieldList
        fields={fields}
        onCopy={(label, value) => {
          void copyText(value).then((ok) => {
            if (ok) onCopied?.(label, value);
          });
        }}
      />
      <p
        style={{
          fontSize: "var(--font-size-micro)",
          color: "var(--text-tertiary)",
          marginTop: "var(--space-sm)",
        }}
      >
        SEPA transfers typically arrive the same business day; the first transfer from a new
        counterparty can take longer.
      </p>
    </section>
  );
}
